import sys

def solve():
    input = sys.stdin.readline
    t = int(input())
    out = []
    for _ in range(t):
        n, k = map(int, input().split())
        s = input().strip()
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1

        first = next(i for i in range(26) if cnt[i] > 0)

        if cnt[first] >= k:
            cnt[first] -= k
            distinct = sum(1 for i in range(26) if cnt[i] > 0)
            if distinct <= 1:
                total_remaining = sum(cnt)
                length = 1 + (total_remaining + k - 1) // k
                out.append(chr(first + 97) * length)
            else:
                res = [chr(first + 97)]
                for i in range(26):
                    if cnt[i] > 0:
                        res.append(chr(i + 97) * cnt[i])
                out.append(''.join(res))
        else:
            need = k - cnt[first]
            for i in range(first + 1, 26):
                if cnt[i] >= need:
                    out.append(chr(i + 97))
                    break
                else:
                    need -= cnt[i]
    sys.stdout.write('\n'.join(out))

if __name__ == "__main__":
    solve()
